    else { const u = ease(cl((t - b) / UP)); o = .9 * (1 - u); k = .9 + .35 * u; }
    return { p, o, k, down: t >= a && t <= b };
  }
  shapeOf(el) {
    if (!el) return 'arrow';
    if (el.closest('input, textarea, [contenteditable], [data-tour-cursor="text"]')) return 'text';
    if (el.closest('[data-tour-cursor="arrow"]')) return 'arrow';
    if (el.closest('a, button, label, select, summary, [role="button"], [role="tab"], [role="switch"], [data-tour-cursor="pointer"]')) return 'pointer';
    return 'arrow';
  }

  /* ── one frame ── */
  render(t, force) {
    t = Math.max(0, Math.min(this.duration, t));
    if (t === this.t && !force) return;
    this.t = t; this.api && (this.api._t = () => this.t);
    this.applyState(t);
    const L = this.L, W = L.W, H = L.H;
    const band = this.S.intro === 0 ? 0 : 1 - ease(cl((t - .3) / (this.S.intro ?? 1.3)));
    const out = ease(cl((t - this.outroAt) / 1.4));
    const base = { s: L.s, x: L.x, y: L.y - L.bandH * L.lift * band };
    let { z, c } = this.camOn ? this.camAt(t) : { z: 1, c: [0, 0] };
    z = Math.pow(z, 1 - out);
    let T = this.camT(z, c, base);
    if (out > 0 && !L.framed) { const k = 1 - .1 * out, px = W / 2, py = L.F.y + L.F.h * .3; T = { s: T.s * k, x: px + (T.x - px) * k, y: py + (T.y - py) * k - H * .04 * out }; }
    this.win.style.transform = `translate(${T.x.toFixed(2)}px,${T.y.toFixed(2)}px) scale(${T.s.toFixed(5)})`;
    // a framed window stays put for the outro (the format's CSS can use --tour-out); a loop fades through its seam
    const seam = this.loop ? Math.min(this.wraps ? ease(cl(t / .4)) : 1, 1 - ease(cl((t - this.duration + .4) / .4))) : 1;
    this.win.style.opacity = String((L.framed ? 1 : 1 - .55 * out) * seam);
    this.root.style.setProperty('--tour-out', out.toFixed(4));
    if (this.band) {      // data-tour-band="css": no slide; the format animates it from --tour-band (1 → 0)
      this.root.style.setProperty('--tour-band', band.toFixed(4));
      if (this.band.dataset.tourBand !== 'css') this.band.style.transform = `translateY(${((1 - band) * 104).toFixed(2)}%)`;
      this.band.style.visibility = band < .001 ? 'hidden' : '';
    }
    if (this.end) { const e = ease(cl((t - this.outroAt - .4) / 1.1)); this.end.style.setProperty('--in', e.toFixed(4)); this.end.style.visibility = e < .001 ? 'hidden' : ''; }
    this.root.style.setProperty('--tour-p', (t / this.duration).toFixed(4));

    // cursor
    const cz = this.touch ? T.s : (1 + (z - 1) * .45) * L.cs;      // a fingertip is part of the screen, so it zooms with it
    if (this.touch) {
      const tu = this.cursorOn ? this.touchAt(t) : null;
      this.cur.style.opacity = tu ? (tu.o * seam).toFixed(3) : '0';
      this._sp = tu ? [T.x + T.s * tu.p[0], T.y + T.s * tu.p[1]] : null; this._co = tu ? tu.o : 0;
      if (tu) this.cur.style.transform = `translate(${(T.x + T.s * tu.p[0]).toFixed(2)}px,${(T.y + T.s * tu.p[1]).toFixed(2)}px) scale(${(cz * tu.k).toFixed(4)})`;
      this.cur.classList.toggle('is-down', !!tu?.down);
    } else {
      const cu = this.cursorAt(t), sp = [T.x + T.s * cu.p[0], T.y + T.s * cu.p[1]];
      const co = (this.cursorOn ? ease(cl((t - this.firstMove + .15) / .35)) * (1 - ease(cl((t - this.outroAt + .3) / .5))) : 0) * cu.vis
      * (L.stack ? cl(1 - Math.max(L.F.y - sp[1], sp[1] - L.F.y - L.F.h) / 24) : 1);   // stacked: never drawn outside the window's frame
      this.cur.style.opacity = co.toFixed(3); this._sp = sp; this._co = co;
      const ml = this.S.pointers?.main?.label;     // pointers.main.label: the person's cursor gets a label too
      if (ml && !this.cur.querySelector('.tour-tag')) { this.cur.dataset.who = 'main'; this.cur.insertAdjacentHTML('beforeend', `<span class="tour-tag"><b>${ml}</b></span>`); }
      this.cur.style.transform = `translate(${sp[0].toFixed(2)}px,${sp[1].toFixed(2)}px) scale(${(cz * (cu.press ? .86 : 1)).toFixed(4)})`;
      if (cu.shape !== this.shapeNow) { this.shapeNow = cu.shape; for (const [k, el] of Object.entries(this.shapes)) el.style.display = k === cu.shape ? '' : 'none'; }
    }
    for (const who of Object.keys(this.tracks)) if (who !== 'main' && this.tracks[who].length) this.drawPointer(who, t, T, cz);
    for (const who in this.curs || {}) if (!this.tracks[who]?.length) this.curs[who].style.opacity = '0';
    // ripples
    let r = 0;
    for (const rp of this.ringAt) {
      const u = (t - rp.t) / .6; if (u < 0 || u > 1 || r >= this.rings.length || !this.cursorOn) continue;
      const q = rp.g.kind === 'drag' ? rp.g.pt : rp.g.ptEnd, el = this.rings[r++]; el.dataset.who = rp.g.who;
      el.style.opacity = ((1 - u) * (this.touch ? .55 : .9)).toFixed(3);
      el.style.transform = `translate(${(T.x + T.s * q[0]).toFixed(1)}px,${(T.y + T.s * q[1]).toFixed(1)}px) scale(${((this.touch ? .85 + ease(u) * .75 : .3 + ease(u) * .9) * cz).toFixed(3)})`;
    }
    for (; r < this.rings.length; r++) this.rings[r].style.opacity = '0';
    // chapter card, caption, keys
    this.fade(this.card, this.chapters, t, (c) => { this.card.children[0].textContent = c.n; this.card.children[1].innerHTML = c.title; this.card.children[2].innerHTML = c.line; this.card.children[2].hidden = !c.line; this.capTop(); });
    this.fade(this.cap, this.capsOn ? this.caps : [], t, (c) => { this.cap.textContent = c.text; });
    this.fade(this.keysEl, this.keyList, t, (c) => { this.keysEl.innerHTML = c.keys.map((k2) => `<kbd>${k2}</kbd>`).join(''); }, .18, .3);
    this.dodge(t, W);
    if (this.keyList.length) { this.keysEl.style.left = W / 2 + 'px'; this.keysEl.style.top = (L.stack ? L.F.y + L.F.h * .78 : Math.min(H * .78, T.y + T.s * this.Hd * .82)) + 'px'; }
    this.onFrame && this.onFrame(t);
  }
  /* the chapter card and caption never sit on what the tour is doing: the cursor, or text being typed or streamed in.
     The card slides to the other side (or steps out if both sides are busy) and comes home once the spot has been
     clear for a moment; the caption lifts to the top. A viewer can close the cards (×); recordings have no ×. */
  dodge(t, W) {
    if (this.L.stack) return;
    const sr = this.stage.getBoundingClientRect(), pad = 16, hot = [];
    if (this._sp && this._co > .05) hot.push([this._sp[0] - pad, this._sp[1] - pad, this._sp[0] + 30 + pad, this._sp[1] + 34 + pad]);
    for (const f of this.focus) if (t >= f.start && t < f.end) for (const e of f.els) {
      const r = e.getBoundingClientRect(); if (r.width || r.height) hot.push([r.left - sr.left - pad, r.top - sr.top - pad, r.right - sr.left + pad, r.bottom - sr.top + pad]);
    }
    const hit = (el, dx = 0, dy = 0) => { const x = el.offsetLeft + dx, y = el.offsetTop + dy, w = el.offsetWidth, h = el.offsetHeight; return hot.some((q) => q[0] < x + w && q[2] > x && q[1] < y + h && q[3] > y); };
    const settle = (el, want) => {     // move away at once; come back only after .8 s clear (either way along the timeline)
      if (this.still || want === el.dataset.dodge) { el.dataset.dodge = want; el._since = t; return; }
      if (want !== 'home' || Math.abs(t - (el._since ?? t)) > .8) { el.dataset.dodge = want; el._since = t; }
    };
    if (this.card._i >= 0 && !this.cardOff) {
      const span = W - this.card.offsetWidth - 2 * this.card.offsetLeft;
      settle(this.card, !hit(this.card) ? 'home' : span > 0 && !hit(this.card, span) ? 'right' : 'hide');
      this.card.style.translate = this.card.dataset.dodge === 'right' ? `${span}px 0` : '';
    }
    if (this.cap._i >= 0) {
      const up = -(this.cap.offsetTop - parseFloat(this.stage.style.getPropertyValue('--su') || 8) * 4);
      settle(this.cap, hit(this.cap) && !hit(this.cap, 0, up) ? 'up' : 'home');
      this.cap.style.translate = this.cap.dataset.dodge === 'up' ? `0 ${up}px` : '';
    }
  }
  capTop() { if (this.L.stack) this.stage.style.setProperty('--cap-top', this.card.offsetTop + this.card.offsetHeight + parseFloat(this.stage.style.getPropertyValue('--su')) * 2.2 + 'px'); }
  fade(el, list, t, fill, fi = .6, fo = .5) {
    const i = list.findIndex((c) => t >= c.start && t < c.end);
    if (i !== (el._i ?? -2)) { el._i = i; if (i >= 0) fill(list[i]); }
    const c = list[i], o = !c ? 0 : this.still && this.fixT == null ? 1 : ease(cl((t - c.start) / fi)) * (1 - ease(cl((t - (c.end - fo)) / fo)));
    el.style.opacity = o.toFixed(3); el.style.setProperty('--o', o.toFixed(3));
  }

  /* ── drivers: scroll (pinned, with autodrift), play (a clock, with controls), record, still ── */
  drivers() {
    const R = this.root;
    R.classList.add('is-' + this.driver);
    if (this.still) {
      R.classList.add('is-still'); R.style.height = '';
      this.begun = true; this.render(this.fixT ?? this.stillAt, true);
      return;
    }
    if (this.rec && !this.host) {
      this.render(0, true);
      this.api.ready.then(() => setTimeout(() => { if (!this.frozen) this.play(); }, (+this.q.get('hold') || 1.2) * 1000));
      return;
    }
    if (this.driver === 'manual') { this.render(0, true); return; }   // the page drives it: play(), pause(), seek(), load(), onFrame
    this.gates.forEach((g) => g.addEventListener('click', (e) => { e.preventDefault(); this.begin(); }));
    if (this.driver === 'play') this.controls();
    else this.scrollDriver();
  }
  begin() {
    if (this.begun) { if (this.driver === 'play') this.toggle(); return; }
    this.begun = true; this.root.classList.add('is-begun');
    this.root.dispatchEvent(new CustomEvent('tour:begin', { bubbles: true }));
    this.music();
    if (this.driver === 'play') this.play(); else this.drift.start();
  }
  music() {
    const src = this.root.dataset.music; if (!src) return;
    const a = (this.audio = new Audio(src)); a.loop = true; a.volume = 0;
    a.play().then(() => { let v = 0; const up = () => { v = Math.min(1, v + .04); a.volume = v; if (v < 1) setTimeout(up, 40); }; up(); }).catch(() => {});
  }
  play() {
    if (this.t >= this.duration - .02) this.t = 0;
    this.frozen = false; this.playing = true; this.root.classList.add('is-playing');
    let t0 = performance.now() - this.t * 1000;
    const loop = (now) => {
      if (!this.playing || !this.alive) return;
      const t = (now - t0) / 1000;
      if (t >= this.duration && this.loop) { t0 = now; this.wraps = (this.wraps || 0) + 1; this.render(0); this.raf = requestAnimationFrame(loop); return; }
      if (t >= this.duration) { this.render(this.duration); this.pause(); this.root.dispatchEvent(new CustomEvent('tour:end', { bubbles: true })); return; }
      this.render(t); this.raf = requestAnimationFrame(loop);
    };
    cancelAnimationFrame(this.raf); this.raf = requestAnimationFrame(loop);
    this.syncCtl && this.syncCtl();
  }
  pause() { this.playing = false; cancelAnimationFrame(this.raf); this.root.classList.remove('is-playing'); this.syncCtl && this.syncCtl(); }
  toggle() { this.playing ? this.pause() : this.play(); }

  controls() {
    const c = document.createElement('div'); c.className = 'tour-ctl';
    c.innerHTML = `<button type="button" class="tour-pp" aria-label="Play"></button>
      <span class="tour-scrub"><input type="range" min="0" max="${this.duration}" step="0.01" value="0" aria-label="Seek">${this.chapters.map((ch) => `<i style="left:${(ch.start / this.duration) * 100}%"></i>`).join('')}</span>
      <span class="tour-time">0:00 / ${fmtTime(this.duration)}</span>`;
    this.stage.append(c);
    const pp = c.querySelector('.tour-pp'), rg = c.querySelector('input'), tm = c.querySelector('.tour-time');
    const PLAY = '<svg viewBox="0 0 20 20"><path d="M6 3.8v12.4L16 10z"/></svg>', PAUSE = '<svg viewBox="0 0 20 20"><path d="M5.5 4h3v12h-3zM11.5 4h3v12h-3z"/></svg>';
    this.syncCtl = () => { pp.innerHTML = this.playing ? PAUSE : PLAY; pp.setAttribute('aria-label', this.playing ? 'Pause' : 'Play'); };
    this.onFrame = (t) => { if (document.activeElement !== rg) rg.value = t; rg.style.setProperty('--v', t / this.duration); tm.textContent = `${fmtTime(t)} / ${fmtTime(this.duration)}`; };
    pp.addEventListener('click', () => { if (!this.begun) this.begin(); else this.toggle(); });
    rg.addEventListener('input', () => { if (!this.begun) { this.begun = true; this.root.classList.add('is-begun'); } this.pause(); this.render(+rg.value); });
    this.root.addEventListener('keydown', (e) => {
      if (e.target.closest('input, textarea, select') && e.target !== rg) return;
      if (e.key === ' ' || e.key === 'k') { e.preventDefault(); this.begin(); }
      if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') { if (e.target === rg) return; e.preventDefault(); this.pause(); this.render(this.t + (e.key === 'ArrowRight' ? 3 : -3)); }
    });
    this.syncCtl(); this.render(0, true);
  }

  scrollDriver() {
    const R = this.root, D = (this.drift = { on: true, done: false, active: false, pos: 0, last: null, lt: 0 });
    const lock = (R.dataset.lock ?? 'true') !== 'false';
    const span = () => R.offsetHeight - this.stage.clientHeight;
    const top = () => R.getBoundingClientRect().top + scrollY;
    const tNow = () => { const s = span(); return s > 0 ? cl((scrollY - top()) / s) * this.duration : 0; };
    // the switch: the one way to take over while it plays itself
    const sw = document.createElement('label'); sw.className = 'tour-drift';
    sw.innerHTML = `<span>Auto-play</span><input type="checkbox" role="switch" checked><i></i><span class="tour-say">It plays by itself. ${matchMedia('(hover: none)').matches ? 'Tap' : 'Click'} here to take over.</span>`;
    this.stage.append(sw);
    const input = sw.querySelector('input');
    input.addEventListener('change', () => { D.on = input.checked; D.last = null; sw.classList.remove('is-saying'); });
    let sayT = 0;
    const locked = () => D.active && D.on && !D.done;
    const block = (e) => { if (!locked() || (e.target instanceof Node && sw.contains(e.target)) || !e.cancelable) return; e.preventDefault(); sw.classList.add('is-saying'); clearTimeout(sayT); sayT = setTimeout(() => sw.classList.remove('is-saying'), 2600); };
    // before the first click, a film at the very top holds the page still (the gate)
    const atTop = top() < 4;
    const hold = (e) => { if (!this.begun && atTop && e.cancelable && scrollY < 4) e.preventDefault(); };
    const KEYS = new Set([' ', 'PageDown', 'PageUp', 'ArrowDown', 'ArrowUp', 'Home', 'End']);
    const onKey = (e) => { if (KEYS.has(e.key) && !e.target?.closest?.('input, textarea, select, button, [contenteditable]')) { block(e); hold(e); } };
    const onWheel = (e) => { if (lock) block(e); hold(e); };
    const onFirst = (e) => {
      if (this.begun || !atTop || scrollY > 4) return;
      if (e.type === 'keydown' && ['Tab', 'Shift', 'Meta', 'Alt', 'Control', 'CapsLock'].includes(e.key)) return;
      if (e.target.closest && e.target.closest('a[href]')) return;
      this.begin();
    };
    addEventListener('wheel', onWheel, { passive: false }); addEventListener('touchmove', onWheel, { passive: false });
    addEventListener('keydown', onKey); addEventListener('pointerdown', onFirst, true); addEventListener('keydown', onFirst, true);
    document.querySelectorAll('a[href^="#"]').forEach((a) => a.addEventListener('click', () => { if (!R.contains(a) || !a.matches('[data-tour-gate]')) { input.checked = false; D.on = false; } }));
    D.start = () => { D.active = true; D.last = null; R.classList.add('is-drifting'); };
    this.cleanup = () => { removeEventListener('wheel', onWheel); removeEventListener('touchmove', onWheel); removeEventListener('keydown', onKey); removeEventListener('pointerdown', onFirst, true); removeEventListener('keydown', onFirst, true); sw.remove(); };
    const pxps = () => this.stage.clientHeight * .3;
    const loop = (now) => {
      if (!this.alive) return;
      const dt = Math.min(.05, (now - D.lt) / 1000 || 0); D.lt = now;
      const endY = top() + span();
      if (D.active && D.on && !D.done && scrollY < endY - 1) {
        if (D.last !== null && Math.abs(scrollY - D.last) > 40) D.pos = scrollY;     // a scrollbar drag: carry on from there
        else if (D.last === null) D.pos = scrollY;
        D.pos = Math.min(endY, D.pos + pxps() * dt);
        scrollTo({ top: D.pos, behavior: 'instant' }); D.last = D.pos;
      }
      if (D.active && scrollY >= endY - 2) D.done = true;
      sw.classList.toggle('is-gone', !D.active || D.done);
      if (!this.frozen) this.render(tNow());
      requestAnimationFrame(loop);
    };
    requestAnimationFrame(loop);
  }

  /* swap in another script on the same window: the product goes back to how the page drew it, then the new
     script is compiled and measured. The playground uses it to turn a visitor's clicks into a live script. */
  load(script) {
    this.pause();
    for (const c of this.ch) { c.last = undefined; this.write(c, c.init); }
    this.S = script; this.compile();
    Object.assign(this.api, { duration: this.duration, chapters: this.chapters.map((c) => ({ t: c.start, n: c.n, title: c.title })), marks: this.marks });
    this.t = -1; this.layout(); this.grow(); this.probe();
    return this.api;
  }

  destroy() { this.alive = false; this.pause(); this.ro?.disconnect(); this.cleanup?.(); this.audio?.pause(); }
}

@import url("../tour/tour.css");
/* demo/changelog: a person's release notes. "Now" first (this month, dated), then their life as a changelog read top
   to bottom, newest first: a release per year, entries tagged Shipped / Joined / Moved / Learned / Wrote. Shipped
   entries carry a small film that plays as it reaches the middle of the screen. A rail of contribution strips (one
   row per release, one cell per week) tracks the scroll. It ends on "Unreleased": a cursor drafts the next entry and
   the address appears.

   Layout comes from section.js, not media queries, so the page and the three recording ratios share one set of rules:
     .is-wide    the rail is a sticky column on the left
     .is-mid     the rail becomes a sticky bar on top (tablets, 1:1 recordings)
     .is-narrow  the same bar, one column (phones, 9:16 recordings)
   Every page size is calc(var(--px) * n): --px is 1px on the page and the record box's share of a design width in
   ?record, so a recording is the page set larger, not a transformed copy (the films measure themselves). */

.demo-changelog{--px:1px;--cl-accent:#2c7552;--cl-accent-soft:#e3eee6;--cl-rail:calc(var(--px)*236);--cl-gap:calc(var(--px)*76);
  --cl-col:calc(var(--px)*760);--cl-g:calc(var(--px)*48);--addr:1;
  display:block;position:relative;font-size:calc(var(--px)*16);color:var(--ink);background:var(--page)}
.demo-changelog.is-mid{--cl-g:calc(var(--px)*40)}
.demo-changelog.is-narrow{--cl-g:calc(var(--px)*18)}
.demo-changelog [hidden]{display:none!important}
.demo-changelog a{text-decoration:none}
.demo-changelog .sf-note{margin-top:calc(var(--px)*14);font-size:calc(var(--px)*11)}

/* the frame everything sits in: the rail column, then the reading column */
.demo-changelog > *{max-width:calc(var(--cl-rail) + var(--cl-gap) + var(--cl-col) + 2 * var(--cl-g));margin-inline:auto;padding-inline:var(--cl-g)}
.demo-changelog:not(.is-wide) > *{max-width:calc(var(--cl-col) + 2 * var(--cl-g))}

/* ── 0. the top line ─────────────────────────────────────────────────────────────────── */
.cl-top{display:flex;align-items:center;gap:calc(var(--px)*26);height:calc(var(--px)*76)}
.cl-name{margin-right:auto;font:400 calc(var(--px)*21)/1 var(--serif);letter-spacing:-.012em}
.cl-nav{display:flex;gap:calc(var(--px)*26);font:500 calc(var(--px)*14)/1 var(--sans);color:var(--ink-2)}
.cl-nav a{transition:color .25s}.cl-nav a:hover{color:var(--ink)}
.is-narrow .cl-nav{gap:calc(var(--px)*16);font-size:calc(var(--px)*13)}
.is-narrow .cl-nav a:nth-child(-n+3){display:none}

/* ── 1. now ───────────────────────────────────────────────────────────────────────────── */
.cl-now{padding-bottom:calc(var(--px)*30)}
.is-wide .cl-now{padding-top:calc(var(--px)*2)}
.cl-now-kick{display:flex;align-items:center;gap:calc(var(--px)*10);margin:0 0 calc(var(--px)*26);font:500 calc(var(--px)*12)/1 var(--sans);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3)}
.cl-now-kick b{font-weight:600;color:var(--ink)}
.cl-now-kick time{letter-spacing:.04em;text-transform:none;font-size:calc(var(--px)*13);font-variant-numeric:tabular-nums}
.cl-now-kick time::before{content:"";display:inline-block;width:calc(var(--px)*18);height:1px;margin:0 calc(var(--px)*10) 0 calc(var(--px)*2);vertical-align:middle;background:var(--rule)}
.cl-now-dot{width:calc(var(--px)*7);height:calc(var(--px)*7);border-radius:50%;background:var(--cl-accent);box-shadow:0 0 0 calc(var(--px)*4) var(--cl-accent-soft)}
.cl-now-line{margin:0;max-width:15.5em;font:400 calc(var(--px)*54)/1.05 var(--serif);letter-spacing:-.022em;text-wrap:balance}
.cl-now-line em{font-style:italic}
.is-mid .cl-now-line{font-size:calc(var(--px)*50)}
.is-narrow .cl-now-line{font-size:calc(var(--px)*36);line-height:1.08}
.cl-now-list{margin:calc(var(--px)*46) 0 0;max-width:calc(var(--px)*680)}
.cl-now-list > div{display:grid;grid-template-columns:calc(var(--px)*120) 1fr;gap:calc(var(--px)*16);padding:calc(var(--px)*13) 0;border-top:1px solid var(--rule)}
.cl-now-list > div:last-child{border-bottom:1px solid var(--rule)}
.cl-now-list dt{padding-top:calc(var(--px)*3);font:500 calc(var(--px)*11.5)/1.3 var(--sans);letter-spacing:.13em;text-transform:uppercase;color:var(--ink-3)}
.cl-now-list dd{margin:0;font:400 calc(var(--px)*17)/1.45 var(--sans);color:var(--ink-2)}
.is-narrow .cl-now-list{margin-top:calc(var(--px)*30)}
.is-narrow .cl-now-list > div{grid-template-columns:1fr;gap:calc(var(--px)*4);padding:calc(var(--px)*11) 0}
.is-narrow .cl-now-list dd{font-size:calc(var(--px)*15.5)}

/* ── 2. the log ───────────────────────────────────────────────────────────────────────── */
.cl-log{position:relative;margin-top:calc(var(--px)*72)}
.is-wide .cl-log{display:grid;grid-template-columns:var(--cl-rail) minmax(0,var(--cl-col));column-gap:var(--cl-gap);align-items:start}
.is-narrow .cl-log{margin-top:calc(var(--px)*34)}

/* the rail: one row per release, one cell per week */
.cl-rail{position:sticky;top:calc(var(--px)*30);z-index:4;padding-top:calc(var(--px)*1)}
.cl-rail-h{display:flex;justify-content:space-between;align-items:baseline;margin:0 0 calc(var(--px)*14);padding-bottom:calc(var(--px)*12);border-bottom:1px solid var(--ink);
  font:500 calc(var(--px)*11.5)/1 var(--sans);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3)}
.cl-rail-h b{font-weight:600;color:var(--ink)}
.cl-years{list-style:none;margin:0;padding:0}
.cl-yr{position:relative;padding:calc(var(--px)*8) 0 calc(var(--px)*9);opacity:.42;transition:opacity .45s var(--ease)}
.cl-yr.is-on{opacity:1}
.cl-yr:hover{opacity:.85}
.cl-yr > a{display:flex;align-items:baseline;gap:calc(var(--px)*10);margin-bottom:calc(var(--px)*7)}
.cl-yr b{font:500 calc(var(--px)*14)/1 var(--sans);font-variant-numeric:tabular-nums;letter-spacing:.01em}
.cl-yr > a span{font:400 calc(var(--px)*12.5)/1 var(--sans);color:var(--ink-3)}
.cl-yr.is-on > a span{color:var(--ink-2)}
.cl-wk{position:relative;display:grid;grid-template-columns:repeat(52,1fr);gap:1px;height:calc(var(--px)*11)}
.cl-wk > i{display:block;min-width:0;border-radius:.5px;background:color-mix(in srgb,var(--ink) calc(var(--lv,0) * 16%),var(--ph-line))}
.cl-wk > i.is-e{background:var(--ink-2);cursor:pointer}
.cl-wk > i.is-ship{background:var(--cl-accent)}
.cl-wk > i.is-e::after{content:"";display:block;height:100%;margin:0 -2px}   /* a wider hit area */
/* the reading head: where in the year the entry at the middle of the screen sits */
.cl-wk::after{content:"";position:absolute;left:calc(var(--head,0) * 100%);top:calc(var(--px)*-4);bottom:calc(var(--px)*-4);width:1.5px;margin-left:-.75px;background:var(--ink);
  opacity:0;transition:left .5s var(--ease),opacity .3s}
.cl-yr.is-on .cl-wk::after{opacity:1}
/* "Next": the release that hasn't happened yet, at the top of the future */
.cl-yr-next .cl-wk{display:block;height:calc(var(--px)*11);background:repeating-linear-gradient(90deg,var(--rule) 0 calc(var(--px)*3),transparent calc(var(--px)*3) calc(var(--px)*6)) center/100% 1px no-repeat}
.cl-yr-next .cl-wk::after{display:none}
.cl-yr-next b{font-style:italic;font-family:var(--serif);font-weight:400;font-size:calc(var(--px)*16)}
.cl-rail-key{display:flex;align-items:center;gap:calc(var(--px)*6);margin:calc(var(--px)*16) 0 0;padding-top:calc(var(--px)*12);border-top:1px solid var(--rule);font:400 calc(var(--px)*11.5)/1 var(--sans);color:var(--ink-3)}
.cl-rail-key i{width:calc(var(--px)*7);height:calc(var(--px)*9);border-radius:.5px;background:var(--ink-2)}
.cl-rail-key i.is-ship{background:var(--cl-accent)}
.cl-rail-key i + i,.cl-rail-key i:not(:first-child){margin-left:calc(var(--px)*10)}

/* on tablets and phones the rail is a bar across the top that shows the release you're reading. The rail itself has
   no height (Now reads under it, uncovered); the bar slides in once the reading reaches the first release. */
.demo-changelog:not(.is-wide) .cl-rail{top:0;height:0;padding:0;margin:0 calc(var(--cl-g) * -1)}
.demo-changelog:not(.is-wide) .cl-years{padding:calc(var(--px)*11) var(--cl-g);background:color-mix(in srgb,var(--page) 94%,transparent);
  -webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);border-bottom:1px solid var(--rule);
  opacity:0;transform:translateY(-100%);pointer-events:none;transition:opacity .35s var(--ease),transform .45s var(--ease)}
.demo-changelog:not(.is-wide).is-reading .cl-years{opacity:1;transform:none;pointer-events:auto}
.demo-changelog:not(.is-wide) .cl-rail-h,.demo-changelog:not(.is-wide) .cl-rail-key{display:none}
.demo-changelog:not(.is-wide) .cl-yr{display:none;opacity:1;padding:0}
.demo-changelog:not(.is-wide) .cl-yr.is-on{display:flex;align-items:center;gap:calc(var(--px)*16)}
.demo-changelog:not(.is-wide) .cl-yr > a{flex:none;margin:0;min-width:calc(var(--px)*94)}
.demo-changelog:not(.is-wide) .cl-wk{flex:1;height:calc(var(--px)*12)}

/* a release: the version, the year, one line */
.cl-release,.cl-next{scroll-margin-top:calc(var(--px)*24)}
.demo-changelog:not(.is-wide) .cl-release,.demo-changelog:not(.is-wide) .cl-next{scroll-margin-top:calc(var(--px)*60)}
.cl-ver{padding:calc(var(--px)*58) 0 calc(var(--px)*20);border-top:1px solid var(--ink)}
.cl-ver h2{display:flex;align-items:baseline;gap:calc(var(--px)*14);margin:0;font-weight:400}
.cl-v{font:400 calc(var(--px)*52)/1 var(--serif);letter-spacing:-.025em}
.cl-y{font:500 calc(var(--px)*15)/1 var(--sans);font-variant-numeric:tabular-nums;color:var(--ink-3);letter-spacing:.02em}
.cl-ver p{margin:calc(var(--px)*10) 0 0;font:400 calc(var(--px)*16)/1.45 var(--sans);color:var(--ink-2)}
.is-narrow .cl-v{font-size:calc(var(--px)*42)}

/* an entry: date, tag, body */
.cl-list{list-style:none;margin:0;padding:0}
.cl-entry{display:grid;grid-template-columns:calc(var(--px)*52) calc(var(--px)*92) minmax(0,1fr);column-gap:calc(var(--px)*18);padding:calc(var(--px)*22) 0 calc(var(--px)*24);border-top:1px solid var(--rule);scroll-margin-top:30vh}
.cl-date{padding-top:calc(var(--px)*3);font:500 calc(var(--px)*13)/1.2 var(--sans);font-variant-numeric:tabular-nums;color:var(--ink-3)}
.cl-tag{align-self:start;display:inline-flex;align-items:center;gap:calc(var(--px)*7);padding-top:calc(var(--px)*4);font:600 calc(var(--px)*10.5)/1 var(--sans);letter-spacing:.13em;text-transform:uppercase;color:var(--ink-2)}
.cl-tag::before{content:"";flex:none;width:calc(var(--px)*6);height:calc(var(--px)*6);border-radius:50%;box-shadow:inset 0 0 0 1.25px currentColor}
.cl-entry[data-tag=shipped] .cl-tag{color:var(--cl-accent)}
.cl-entry[data-tag=shipped] .cl-tag::before{background:currentColor}
.cl-body h3{margin:0;font:500 calc(var(--px)*18.5)/1.3 var(--sans);letter-spacing:-.01em}
.cl-body h3 span{font-weight:400;color:var(--ink-3)}
.cl-body h3 span::before{content:" — "}
.cl-body > p{margin:calc(var(--px)*6) 0 0;max-width:36em;font:400 calc(var(--px)*15.5)/1.55 var(--sans);color:var(--ink-2)}
.cl-meta{display:flex;flex-wrap:wrap;align-items:center;gap:calc(var(--px)*8) calc(var(--px)*20);margin-top:calc(var(--px)*14)!important;font-size:calc(var(--px)*13.5)!important}
.cl-meta a{color:var(--ink);box-shadow:inset 0 -1px 0 var(--rule);transition:box-shadow .25s}
.cl-meta a:hover{box-shadow:inset 0 -1px 0 var(--ink)}
.cl-again{margin-left:auto;padding:0;border:0;background:none;font:500 calc(var(--px)*12.5)/1 var(--sans);color:var(--ink-3);cursor:pointer}
.cl-again::before{content:"↺ "}
.cl-again:hover{color:var(--ink)}
.cl-film + .cl-meta{margin-top:calc(var(--px)*22)!important}
.cl-still{margin-top:calc(var(--px)*16);max-width:calc(var(--px)*420)}
.is-narrow .cl-entry{grid-template-columns:auto 1fr;row-gap:calc(var(--px)*8);padding:calc(var(--px)*20) 0}
.is-narrow .cl-date{padding:0}
.is-narrow .cl-tag{padding:calc(var(--px)*1) 0 0}
.is-narrow .cl-body{grid-column:1 / -1}
.is-narrow .cl-body h3{font-size:calc(var(--px)*17.5)}
.is-narrow .cl-body h3 span{display:block}
.is-narrow .cl-body h3 span::before{content:none}
.is-narrow .cl-body > p{font-size:calc(var(--px)*15)}

/* ── a small film inside an entry ─────────────────────────────────────────────────────── */
.demo-changelog .cl-film{--tour-stage:transparent;margin-top:calc(var(--px)*18)}
.demo-changelog .cl-stage{aspect-ratio:16/10}
.demo-changelog .cl-stage,html.tour-record .demo-changelog .cl-film .cl-stage{position:relative;inset:auto;top:auto;height:auto;overflow:visible;background:transparent;isolation:isolate}
.demo-changelog .cl-film.is-square .cl-stage,.is-narrow .cl-film .cl-stage{aspect-ratio:1/1}
.cl-frame{position:absolute;inset:0;border-radius:calc(var(--px)*9);background:var(--ph);
  box-shadow:0 0 0 1px rgba(25,24,22,.09),0 calc(var(--px)*26) calc(var(--px)*48) calc(var(--px)*-30) rgba(25,24,22,.4),0 calc(var(--px)*6) calc(var(--px)*14) calc(var(--px)*-8) rgba(25,24,22,.14)}
.demo-changelog .cl-film [data-tour-window]{border-radius:0;box-shadow:none}
.cl-film .tour-cur{z-index:8}

/* the terminal */
.clt{padding:26px 32px;font:400 16.5px/1.78 var(--mono);color:var(--tour-term-ink,#ebe5d9);overflow:hidden}
.clt p{margin:0;white-space:nowrap}
.clt-dir{color:#8db8d9;margin-right:9px}
.clt-ps{color:var(--tour-term-dim,#a39b8e);margin-right:9px}
.clt-cmd.is-caret::after,.cln-typed.is-caret::after{content:"";display:inline-block;width:.55em;height:1.1em;margin-left:1px;vertical-align:-.18em;background:currentColor;opacity:.85}
.clt-o{display:none}.clt-o.is-in{display:block}
.clt-ok{color:#93c99f;margin-right:10px}
.clt-dim{color:var(--tour-term-dim,#a39b8e)}
.clt-dim b{font-weight:500;color:var(--tour-term-ink,#ebe5d9)}
.clt-box{margin:10px 0 8px;padding:12px 16px 10px;border:1px solid rgba(255,255,255,.14);border-radius:6px;opacity:var(--in,1)}
.clt-bh{display:flex;justify-content:space-between;margin-bottom:6px!important}
.clt-bh span:first-child{color:#e8c48a}
.clt-row{display:grid!important;grid-template-columns:84px 1fr 48px;align-items:center;gap:14px;opacity:0}
.clt-row.is-in{opacity:var(--in,1)}
.clt-row i{display:block;height:6px;width:calc(var(--w) * var(--in,1));border-radius:3px;background:rgba(235,229,217,.22)}
.clt-row .clt-ok{margin:0;opacity:calc(var(--in,1) * 1)}
.clt-k{color:var(--tour-term-dim,#a39b8e)}
.is-square .clt{padding:20px 20px;font-size:14.5px}
.is-square .clt-dir{display:none}
.is-square .clt-o1:not(.clt-l){white-space:normal}

/* the project page */
.clr{position:relative;display:flex;flex-direction:column;background:#fff;font:400 13px/1.45 var(--sans);color:var(--ink);overflow:hidden}
.clr-head{flex:none;display:flex;align-items:center;gap:8px;height:50px;padding:0 22px;border-bottom:1px solid var(--ph-line);font-size:15px}
.clr-mark{width:20px;height:20px;border-radius:5px;background:var(--page-2);box-shadow:inset 0 0 0 1px var(--ph-line);margin-right:4px}
.clr-owner{color:var(--ink-2)}.clr-sl{color:var(--ink-3)}
.clr-head b{font-weight:600}
.clr-tagv{margin-left:6px;padding:3px 8px;border-radius:99px;box-shadow:inset 0 0 0 1px var(--ph-line);font:500 11px/1 var(--mono);color:var(--ink-2)}
.clr-grid{flex:1;display:grid;grid-template-columns:1fr 176px;gap:30px;padding:22px 22px 0;min-height:0}
.clr-readme h4{margin:0;font:400 28px/1.05 var(--serif);letter-spacing:-.02em}
.clr-lead{margin:7px 0 16px;color:var(--ink-2);font-size:14px}
.clr-install{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 8px 8px 14px;border-radius:7px;background:var(--page);box-shadow:inset 0 0 0 1px var(--ph-line)}
.clr-install code{font:400 13px/1 var(--mono)}
.clr-dim{color:var(--ink-3)}
.clr-install button{min-width:66px;height:28px;padding:0 12px;border:0;border-radius:5px;background:#fff;box-shadow:0 0 0 1px var(--ph-line),0 1px 2px rgba(0,0,0,.06);font:500 12px/1 var(--sans);color:var(--ink);transition:background-color .2s,color .2s}
.clr-install button.is-hover{background:var(--page-2)}
.clr-install button.is-press{transform:scale(.97)}
.clr-install button.is-done{background:var(--cl-accent);color:#fff;box-shadow:none}
.clr-h5{margin:20px 0 8px;font:600 10.5px/1 var(--sans);letter-spacing:.13em;text-transform:uppercase;color:var(--ink-3)}
.clr-code{display:grid;gap:9px;padding:14px 16px;border-radius:7px;background:var(--page)}
.clr-code i{display:block;height:7px;width:var(--w);margin-left:calc(var(--x,0) * 20px);border-radius:4px;background:var(--ph-mark)}
.clr-side{display:flex;flex-direction:column;gap:9px}
.clr-sh{margin:0;font:600 10.5px/1 var(--sans);letter-spacing:.13em;text-transform:uppercase;color:var(--ink-3)}
.clr-sh + .clr-rel{margin-bottom:12px}
.clr-rel{display:flex;align-items:center;gap:9px;padding:9px 11px;border-radius:7px;box-shadow:inset 0 0 0 1px var(--ph-line);cursor:pointer;transition:background-color .2s}
.clr-rel b{font:600 13px/1 var(--mono)}
.clr-rel span{padding:3px 7px;border-radius:99px;background:var(--cl-accent-soft);color:var(--cl-accent);font:600 10.5px/1 var(--sans)}
.clr-rel.is-hover{background:var(--page)}
.clr-side .ph-text{font-size:12px}
.clr-notes{position:absolute;top:50px;right:0;bottom:0;width:316px;padding:22px 24px;background:#fff;border-left:1px solid var(--ph-line);
  box-shadow:-24px 0 40px -30px rgba(25,24,22,.4);transform:translateX(calc((1 - var(--in,0)) * 104%));visibility:visible}
.clr-nk{display:flex;align-items:center;gap:8px;margin:0}
.clr-nk b{font:600 13px/1 var(--mono)}
.clr-nk span{padding:3px 7px;border-radius:99px;background:var(--cl-accent-soft);color:var(--cl-accent);font:600 10.5px/1 var(--sans)}
.clr-notes h4{margin:10px 0 4px;font:400 22px/1.1 var(--serif);letter-spacing:-.015em}
.clr-nh{margin:16px 0 8px;font:600 10.5px/1 var(--sans);letter-spacing:.13em;text-transform:uppercase;color:var(--ink-3)}
.clr-notes ul{list-style:none;margin:0;padding:0;display:grid;gap:9px}
.clr-li{display:flex;align-items:center;gap:10px;opacity:0;transform:translateX(calc((1 - var(--in,0)) * 8px))}
.clr-li.is-in{opacity:var(--in,1)}
.clr-li::before{content:"";flex:none;width:5px;height:5px;border-radius:50%;background:var(--ink-3)}
.clr-li i{display:block;height:7px;width:var(--w);border-radius:4px;background:var(--ph-mark)}
.is-square .clr-head{padding:0 16px;font-size:14px}
.is-square .clr-tagv{display:none}
.is-square .clr-grid{grid-template-columns:1fr;gap:16px;padding:16px 18px 0;align-content:start}
.is-square .clr-side{order:-1;flex-direction:row;align-items:center;gap:12px}
.is-square .clr-side .clr-sh + .clr-rel{margin:0}
.is-square .clr-side > :nth-child(n+3){display:none}
.is-square .clr-readme h4{font-size:24px}
.is-square .clr-lead{margin-bottom:12px}
.is-square .clr-install code{font-size:12px}
.is-square .clr-notes{left:0;width:auto;border-left:0;padding:20px 20px}

/* the app */
.cla{position:relative;display:grid;grid-template-columns:168px 1fr;background:#fff;font:400 13px/1.4 var(--sans);color:var(--ink);overflow:hidden}
.cla-side{padding:16px 12px;background:var(--page);border-right:1px solid var(--ph-line)}
.cla-app{display:flex;align-items:center;gap:9px;margin:0 6px 18px;font-weight:600;font-size:14px}
.cla-app i{width:18px;height:18px;border-radius:5px;background:var(--ink)}
.cla-nav{margin:0 0 2px;padding:8px 10px;border-radius:6px;color:var(--ink-2)}
.cla-nav.is-on{background:#fff;color:var(--ink);box-shadow:0 0 0 1px var(--ph-line)}
.cla-main{display:flex;flex-direction:column;min-width:0}
.cla-bar{display:flex;align-items:center;justify-content:space-between;height:56px;padding:0 20px;border-bottom:1px solid var(--ph-line)}
.cla-bar b{font:400 22px/1 var(--serif);letter-spacing:-.015em}
.cla-new{height:30px;padding:0 13px;border:0;border-radius:6px;background:var(--ink);color:#fff;font:500 12.5px/1 var(--sans);transition:background-color .2s}
.cla-new.is-hover{background:#000}
.cla-new.is-press{transform:scale(.96)}
.cla-list{padding:6px 12px}
.cla-row{display:grid;grid-template-columns:14px 1fr 54px;align-items:center;gap:12px;height:46px;padding:0 10px;border-radius:7px;border-bottom:1px solid var(--page-2)}
.cla-row i{display:block;height:7px;width:var(--w);border-radius:4px;background:var(--ph-mark)}
.cla-dot{width:10px;height:10px;border-radius:50%;box-shadow:inset 0 0 0 1.5px var(--ph-mark)}
.cla-when{justify-self:end;font-size:11.5px;color:var(--ink-3)}
.cla-row-new{height:calc(var(--in,0) * 46px);min-height:0;overflow:hidden;opacity:var(--in,0);background:var(--cl-accent-soft);border-bottom:0}
.cla-row-new > *{margin-block:auto}
.cla-row-new .cla-dot{background:var(--cl-accent);box-shadow:none}
.cla-row-new .cla-when{color:var(--cl-accent)}
.cla-name{font-weight:500;min-height:1.3em;white-space:nowrap;overflow:hidden}
.cla-name.is-caret::after{content:"";display:inline-block;width:1.5px;height:1.15em;margin-left:1px;vertical-align:-.2em;background:var(--ink)}
.cla-row-new.is-sel{box-shadow:inset 0 0 0 1.5px var(--cl-accent)}
.cla-detail{position:absolute;top:0;right:0;bottom:0;width:292px;padding:18px 20px;background:#fff;border-left:1px solid var(--ph-line);
  box-shadow:-24px 0 40px -30px rgba(25,24,22,.4);transform:translateX(calc((1 - var(--in,0)) * 104%))}
.cla-dh{margin:14px 0 10px;font:400 22px/1.1 var(--serif);letter-spacing:-.015em}
.cla-detail .ph-text{font-size:12px}
.is-square .cla{grid-template-columns:1fr}
.is-square .cla-side{display:none}
.is-square .cla-detail{width:auto;left:0;border-left:0}

/* ── 3. unreleased ─────────────────────────────────────────────────────────────────────── */
.cl-next{padding-bottom:calc(var(--px)*40)}
.cl-next .cl-ver{border-top:1px dashed var(--ink-3)}
.cl-next .cl-v{font-style:italic}
.cl-film-next{margin-top:calc(var(--px)*2);border-top:1px solid var(--rule)}
.cl-film-next .cl-stage{aspect-ratio:760/220}
.demo-changelog .cl-film-next.is-square .cl-stage,.is-narrow .cl-film-next .cl-stage{aspect-ratio:360/316}
.cl-film-next .cl-frame{background:transparent;box-shadow:none}
.cl-film-next [data-tour-window]{background:transparent}
.cln{display:grid;grid-template-columns:52px 92px minmax(0,1fr);column-gap:18px;align-content:start;padding:22px 0 0;font-family:var(--sans);color:var(--ink)}
.cln-date{padding-top:5px;font:500 13px/1.2 var(--sans);color:var(--ink-3)}
.cln-tag{position:relative;align-self:start;height:16px;margin-top:4px}
.cln-tag b{position:absolute;left:0;top:0;display:inline-flex;align-items:center;gap:7px;white-space:nowrap;font:600 10.5px/1 var(--sans);letter-spacing:.13em;text-transform:uppercase;transition:none}
.cln-tag b::before{content:"";width:6px;height:6px;border-radius:50%;box-shadow:inset 0 0 0 1.25px currentColor}
.cln-t0{color:var(--ink-3);opacity:calc(1 - var(--out,0))}
.cln-t1{color:var(--cl-accent);opacity:var(--out,0);transform:translateY(calc((1 - var(--out,0)) * 6px))}
.cln-t1::before{background:currentColor}
.cln-field{position:relative;margin:0;padding:13px 16px 14px;border:1px dashed var(--ink-3);border-radius:6px;font:400 27px/1.2 var(--serif);letter-spacing:-.015em;color:var(--ink);min-height:62px;transition:border-color .3s,background-color .3s}
.cln-field.is-hover,.cln-field.is-press{border-color:var(--ink-2)}
.cln-ph{color:var(--ink-3);font-style:italic}
.cln-field:has(.cln-typed:not(:empty)) .cln-ph,.cln-field.is-focus .cln-ph{display:none}
.cln-typed.is-caret::after{width:2px;height:1em;vertical-align:-.12em;opacity:1}
.cln.is-out .cln-field{border-style:solid;border-color:var(--rule);background:#fff}
.cln-sub{margin:9px 0 0;font:400 14.5px/1.4 var(--sans);color:var(--ink-3);opacity:var(--in,0)}
.cln-act{display:flex;align-items:center;justify-content:flex-end;gap:14px;margin-top:12px}
.cln-hint{font:500 12px/1 var(--sans);letter-spacing:.06em;color:var(--ink-3)}
.cln-rel{height:34px;padding:0 16px;border:0;border-radius:4px;background:var(--ink);color:var(--page);font:500 13.5px/1 var(--sans);transition:background-color .25s,transform .1s}
.cln-rel.is-hover{background:#000}
.cln-rel.is-press{transform:scale(.96)}
.cln.is-out .cln-rel{background:var(--cl-accent)}
.cln-rel::before{content:"✓ ";display:none}
.cln.is-out .cln-rel::before{display:inline}
.is-square .cln{grid-template-columns:auto 1fr;row-gap:12px;padding-top:18px}
.is-square .cln-body{grid-column:1 / -1}
.is-square .cln-field{font-size:24px}

.cl-addr{margin-top:calc(var(--px)*18);opacity:var(--addr);transform:translateY(calc((1 - var(--addr)) * var(--px) * 12))}
.is-wide .cl-addr,.is-mid .cl-addr{padding-left:calc(var(--px)*180)}
.cl-mail{display:inline-block;font:400 calc(var(--px)*46)/1.05 var(--serif);letter-spacing:-.022em;box-shadow:inset 0 calc(var(--px)*-2) 0 var(--rule);transition:box-shadow .3s}
.cl-mail:hover{box-shadow:inset 0 calc(var(--px)*-2) 0 var(--ink)}
.is-narrow .cl-mail{font-size:calc(var(--px)*30);word-break:break-word}
.cl-addr-more{display:flex;flex-wrap:wrap;gap:calc(var(--px)*8) calc(var(--px)*22);margin:calc(var(--px)*18) 0 0;font:400 calc(var(--px)*14)/1.3 var(--sans);color:var(--ink-2)}
.cl-addr-more a{color:var(--ink);box-shadow:inset 0 -1px 0 var(--rule)}
.cl-addr-more span{color:var(--ink-3)}

.cl-foot{padding-block:calc(var(--px)*36) calc(var(--px)*48)}
.cl-foot p{margin:0;padding-top:calc(var(--px)*18);border-top:1px solid var(--rule);font:400 calc(var(--px)*12.5)/1.4 var(--sans);color:var(--ink-3)}
.is-wide .cl-foot p{margin-left:calc(var(--cl-rail) + var(--cl-gap))}

/* ── ?record: the page, read top to bottom on its own ─────────────────────────────────── */
html.tour-record .demo-changelog.is-record{overflow:hidden;background:var(--page);scrollbar-width:none}
html.tour-record .demo-changelog.is-record::-webkit-scrollbar{display:none}
.demo-changelog.is-record .cl-again,.demo-changelog.is-record .sf-note{display:none!important}
.demo-changelog.is-record .cl-foot{padding-bottom:calc(var(--px)*240)}
.demo-changelog.is-record *{cursor:none!important}

@media (prefers-reduced-motion:reduce){.cl-yr,.cl-wk::after,.cl-years{transition:none!important}}

/* StyleFeatures scaffolds: the shared placeholder kit.
   Every scaffold section links this first. Tokens can be overridden per site in site.json "theme". */
:root{
  --page:#f5f3ef;--page-2:#ece9e3;--ph:#ffffff;--ph-line:#e3dfd7;--ph-mark:#d9d4ca;
  --ink:#191816;--ink-2:#5f5a53;--ink-3:#9c968c;--rule:#d8d3c9;
  --note:#c2643f;--note-bg:#fbf1ea;
  --serif:'Newsreader',Georgia,serif;--sans:'Inter Tight',system-ui,-apple-system,sans-serif;--mono:ui-monospace,'SF Mono',Menlo,monospace;
  --gutter:clamp(16px,3.4vw,48px);--max:1280px;--radius:2px;
  --ease:cubic-bezier(.2,.7,.2,1);
}
*{box-sizing:border-box}
html{background:var(--page);-webkit-text-size-adjust:100%}
body{margin:0;background:var(--page);color:var(--ink);font-family:var(--sans);-webkit-font-smoothing:antialiased;overflow-x:hidden}
a{color:inherit}
img{display:block;max-width:100%}
.sf-wrap{max-width:var(--max);margin:0 auto;padding-inline:var(--gutter)}
.sf-sec{padding-block:clamp(72px,12vh,140px)}

/* ── type ───────────────────────────────────────────── */
.sf-eyebrow{margin:0 0 18px;font:500 12px/1 var(--sans);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3)}
.sf-h1{margin:0;font:400 clamp(44px,6.4vw,96px)/.98 var(--serif);letter-spacing:-.025em}
.sf-h2{margin:0;font:400 clamp(32px,4vw,58px)/1.02 var(--serif);letter-spacing:-.02em}
.sf-h3{margin:0;font:500 clamp(19px,1.6vw,23px)/1.2 var(--sans);letter-spacing:-.01em}
.sf-lede{margin:0;max-width:34em;font:400 clamp(17px,1.4vw,20px)/1.5 var(--sans);color:var(--ink-2)}
.sf-small{font:400 13px/1.45 var(--sans);color:var(--ink-3)}

/* ── placeholder image: <figure class="ph" style="--r:4/5" data-ph="Image · 4:5" data-hint="What goes here"></figure> */
.ph{position:relative;margin:0;aspect-ratio:var(--r,4/3);background:var(--ph);border-radius:var(--radius);overflow:hidden;
  box-shadow:inset 0 0 0 1px var(--ph-line);min-width:0}
.ph::before{content:"";position:absolute;inset:0;pointer-events:none;
  background:
    linear-gradient(to top right,transparent calc(50% - .5px),var(--ph-mark) calc(50% - .5px),var(--ph-mark) calc(50% + .5px),transparent calc(50% + .5px)),
    linear-gradient(to bottom right,transparent calc(50% - .5px),var(--ph-mark) calc(50% - .5px),var(--ph-mark) calc(50% + .5px),transparent calc(50% + .5px));
  opacity:.55}
.ph::after{content:attr(data-ph) "\A" attr(data-hint);white-space:pre-line;position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
  width:max-content;max-width:min(80%,24em);padding:9px 13px;background:var(--ph);text-align:center;
  font:500 11px/1.45 var(--sans);letter-spacing:.06em;text-transform:uppercase;color:var(--ink-3);border-radius:var(--radius)}
.ph[data-hint]::after{font-size:11px}
.ph.is-bare::after{content:none}
.ph.is-round{border-radius:50%}
.ph.is-tone{--ph:var(--page-2)}              /* a placeholder on a white card */
.ph > *{position:relative;z-index:1}

/* video placeholder: add .ph-video; scaffold.js adds the transport */
.ph-video{--ph:#f7f6f3}
.ph-video::before{opacity:.35}
.ph-video::after{top:auto;bottom:44px;transform:translateX(-50%);max-width:min(86%,26em)}   /* label sits low, clear of the play button */
.ph-play{position:absolute;z-index:2;left:50%;top:50%;width:56px;height:56px;margin:-28px 0 0 -28px;border:0;border-radius:50%;
  background:var(--ink);color:var(--page);cursor:pointer;display:grid;place-items:center;transition:transform .4s var(--ease)}
.ph-play:hover{transform:scale(1.06)}
.ph-play[hidden],.ph-bar[hidden]{display:none}
.ph-play svg{width:20px;height:20px}
.ph-play:focus-visible{outline:2px solid var(--note);outline-offset:4px}
.ph-bar{position:absolute;z-index:2;left:16px;right:16px;bottom:14px;display:flex;align-items:center;gap:12px;font:500 11px/1 var(--mono);color:var(--ink-3)}
.ph-track{flex:1;height:2px;background:var(--ph-line);position:relative;overflow:hidden}
.ph-track i{position:absolute;inset:0;background:var(--ink);transform-origin:left;transform:scaleX(var(--p,0))}
.ph-video.is-playing::before{animation:ph-breathe 3.2s ease-in-out infinite}
@keyframes ph-breathe{50%{opacity:.12}}

/* placeholder copy: <p class="ph-text" style="--n:3"></p>  (n lines, last one short) */
.ph-text{--lh:1.6em;display:block;margin:0;height:calc(var(--n,3) * var(--lh));max-width:32em;
  background:repeating-linear-gradient(to bottom,var(--ph-line) 0 .55em,transparent .55em var(--lh));
  -webkit-mask:linear-gradient(#000,#000) top/100% calc(100% - var(--lh)) no-repeat,linear-gradient(90deg,#000 var(--last,58%),transparent 0) bottom/100% var(--lh) no-repeat;
          mask:linear-gradient(#000,#000) top/100% calc(100% - var(--lh)) no-repeat,linear-gradient(90deg,#000 var(--last,58%),transparent 0) bottom/100% var(--lh) no-repeat}
.ph-logo{display:inline-flex;align-items:center;justify-content:center;height:34px;min-width:110px;padding:0 14px;border-radius:var(--radius);
  box-shadow:inset 0 0 0 1px var(--ph-line);background:var(--ph);font:600 11px/1 var(--sans);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3)}

/* ── controls ───────────────────────────────────────── */
.sf-btn{display:inline-flex;align-items:center;gap:10px;padding:14px 22px;border:0;border-radius:var(--radius);background:var(--ink);color:var(--page);
  font:500 14px/1 var(--sans);text-decoration:none;cursor:pointer;transition:background-color .3s ease,color .3s ease,box-shadow .3s ease}
.sf-btn:hover{background:#000}
.sf-btn--ghost{background:transparent;color:var(--ink);box-shadow:inset 0 0 0 1px var(--ink)}
.sf-btn--ghost:hover{background:var(--ink);color:var(--page)}
.sf-btn--text{padding:6px 0;background:none;color:var(--ink);box-shadow:inset 0 -1px 0 currentColor}
.sf-btn--text:hover{background:none;color:var(--ink-2)}
.sf-btn:focus-visible,.sf-field:focus-visible{outline:2px solid var(--note);outline-offset:3px}
.sf-field{width:100%;padding:14px 0;border:0;border-bottom:1px solid var(--rule);background:transparent;font:400 16px/1.2 var(--sans);color:var(--ink);border-radius:0}
.sf-field::placeholder{color:var(--ink-3)}
.sf-rule{height:0;border:0;border-top:1px solid var(--rule);margin:0}

/* ── notes: what goes here / who it suits. <span class="sf-note">Swap for your logo</span>; html.sf-clean hides them */
.sf-note{display:inline-flex;align-items:center;gap:7px;padding:5px 9px 5px 7px;border-radius:var(--radius);background:var(--note-bg);color:var(--note);
  font:500 11px/1.25 var(--sans);letter-spacing:.01em;vertical-align:middle;white-space:normal;max-width:30em}
.sf-note::before{content:"";flex:none;width:6px;height:6px;border-radius:50%;background:currentColor}
.sf-note.is-pin{position:absolute;z-index:5}
html.sf-clean .sf-note{display:none!important}

/* ── reveal ─────────────────────────────────────────── */
[data-reveal]{opacity:0;transform:translateY(14px);transition:opacity 1s var(--ease),transform 1.2s var(--ease);transition-delay:calc(var(--i,0) * 80ms)}
[data-reveal].is-in{opacity:1;transform:none}
.no-js [data-reveal]{opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){[data-reveal]{opacity:1;transform:none;transition:none}}

/* ── preview spec card (only on preview pages) ───────── */
.sf-spec{position:fixed;z-index:9999;left:14px;bottom:14px;max-width:min(360px,calc(100vw - 28px));padding:14px 16px;border-radius:4px;
  background:rgba(255,255,255,.94);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);box-shadow:0 0 0 1px var(--ph-line),0 10px 30px -14px rgba(0,0,0,.3);
  font:400 12px/1.45 var(--sans);color:var(--ink-2)}
.sf-spec b{display:block;font:500 14px/1.25 var(--sans);color:var(--ink);margin:6px 0 3px}
.sf-spec .sf-kind{margin-right:6px}
.sf-spec ul{list-style:none;margin:8px 0 0;padding:0;display:flex;flex-wrap:wrap;gap:5px}
.sf-spec li{padding:3px 7px;border-radius:2px;background:var(--page);color:var(--ink-2);font-size:11px}
.sf-spec button{margin-top:10px;padding:0;border:0;background:none;font:500 11px/1 var(--sans);color:var(--ink-3);text-decoration:underline;cursor:pointer}
.sf-spec.is-min p,.sf-spec.is-min ul{display:none}
.sf-thumb .sf-spec{display:none}
@media (max-width:700px){.sf-spec{left:8px;bottom:8px;padding:10px 12px}}
.sf-kind{display:inline-flex;align-items:center;gap:6px;padding:4px 8px 4px 7px;border-radius:2px;font:600 10px/1 var(--sans);letter-spacing:.12em;text-transform:uppercase}
.sf-kind::before{content:"";width:7px;height:7px;border-radius:50%;background:currentColor}
.sf-kind--static{background:#eceae5;color:#6f6a62}
.sf-kind--interactive{background:#fbeee6;color:#b65a35}
.sf-kind--video{background:#1d1c1a;color:#f2efe9}

/* tour.css: the engine's own look. Window chromes, the cursor, ripples, chapter card, caption, key caps,
   the play controls, the auto-play switch and the ?record stage. Shared by every demo film; a template
   restyles it through these tokens rather than editing it:
     --tour-stage  backdrop behind the window        --tour-win-radius  window corners (design px)
     --tour-ring   click ripple colour               --tour-cap-bg / --tour-cap-ink  caption pill
   Sizes on the stage scale with --su (a hundredth of the stage's short side, set by tour.js). */

[data-tour-root]{position:relative;--tour-stage:var(--page-2,#ece9e3);--tour-ring:rgba(25,24,22,.42);--tour-cap-bg:var(--ink,#191816);--tour-cap-ink:var(--page,#f5f3ef);--tour-win-radius:12px}
[data-tour-stage]{position:sticky;top:0;height:100svh;overflow:hidden;background:var(--tour-stage);isolation:isolate;--su:9px}
[data-tour-root].is-play [data-tour-stage],[data-tour-root].is-still [data-tour-stage]{position:relative}
.tour-rig{position:absolute;inset:0}

/* the window: design pixels, scaled by the camera */
[data-tour-window]{position:absolute;left:0;top:0;transform-origin:0 0;display:flex;flex-direction:column;overflow:hidden;
  border-radius:var(--tour-win-radius);background:var(--ph,#fff);
  box-shadow:0 0 0 1px rgba(25,24,22,.12),0 40px 90px -40px rgba(25,24,22,.5),0 12px 28px -16px rgba(25,24,22,.28)}
[data-tour-window] > :not(.tour-chrome){flex:1;min-height:0}
.tour-chrome{flex:none;height:40px;display:flex;align-items:center;gap:14px;padding:0 14px;background:var(--page,#f5f3ef);border-bottom:1px solid var(--ph-line,#e3dfd7);font:500 12.5px/1 var(--sans,system-ui);color:var(--ink-2,#5f5a53)}
.tour-lights{display:flex;gap:8px}
.tour-lights i{width:12px;height:12px;border-radius:50%;background:#ec6a5e;box-shadow:inset 0 0 0 .5px rgba(0,0,0,.12)}
.tour-lights i+i{background:#f4bf4f}.tour-lights i+i+i{background:#61c554}
.tour-navs{display:flex;gap:10px}.tour-navs.is-end{margin-left:auto}
.tour-chrome svg{width:15px;height:15px;fill:none;stroke:var(--ink-3,#9c968c);stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.tour-url{flex:0 1 420px;margin-left:auto;display:flex;align-items:center;justify-content:center;gap:7px;height:26px;padding:0 14px;border-radius:7px;background:var(--ph,#fff);box-shadow:inset 0 0 0 1px var(--ph-line,#e3dfd7);font-weight:400;color:var(--ink-2,#5f5a53);white-space:nowrap;overflow:hidden}
.tour-url svg{width:12px;height:12px}
.tour-chrome[data-kind=app]{height:38px;justify-content:center;position:relative}
.tour-chrome[data-kind=app] .tour-lights{position:absolute;left:14px;top:13px}
.tour-chrome[data-kind=phone]{height:46px;justify-content:space-between;padding:0 26px;background:transparent;border:0;font:600 15px/1 var(--sans,system-ui);color:var(--ink,#191816)}
.tour-notch{width:120px;height:32px;border-radius:20px;background:#111}
.tour-status{display:flex;gap:4px}.tour-status i{width:16px;height:10px;border-radius:2px;background:var(--ink,#191816)}
[data-chrome=phone]{--tour-win-radius:54px;box-shadow:0 0 0 10px #111,0 0 0 11px #333,0 40px 90px -30px rgba(25,24,22,.55)}
[data-chrome=none]{--tour-win-radius:8px}
/* terminal: a warm charcoal window (tokens --tour-term-bg, --tour-term-bar, --tour-term-ink, --tour-term-dim) */
[data-chrome=terminal]{background:var(--tour-term-bg,#1d1b18);color:var(--tour-term-ink,#ebe5d9)}
.tour-chrome[data-kind=terminal]{height:38px;justify-content:center;position:relative;background:var(--tour-term-bar,#272420);border-bottom:1px solid rgba(255,255,255,.07);color:var(--tour-term-dim,#a39b8e);font-weight:500}
.tour-chrome[data-kind=terminal] .tour-lights{position:absolute;left:14px;top:13px}
.tour-chrome[data-kind=terminal] .tour-lights i{box-shadow:inset 0 0 0 .5px rgba(0,0,0,.3)}
/* windows inside the window: any [data-chrome] element in the product gets its own chrome and frame */
[data-tour-window] [data-chrome]{display:flex;flex-direction:column;overflow:hidden;border-radius:var(--tour-win-radius)}
[data-tour-window] [data-chrome] > :not(.tour-chrome){flex:1;min-height:0}

/* cursor and ripples (stage coordinates) */
.tour-cur{position:absolute;left:0;top:0;z-index:8;width:0;height:0;pointer-events:none;opacity:0;transform-origin:0 0}
.tour-cur svg{position:absolute;left:-1px;top:-1px;overflow:visible;filter:drop-shadow(0 1px 1.5px rgba(0,0,0,.35)) drop-shadow(0 3px 6px rgba(0,0,0,.12))}
.tour-cur .tour-arrow path{fill:#141312;stroke:#fff;stroke-width:1.3}
.tour-cur .tour-hand{left:-8px;top:-2px}
.tour-cur .tour-hand path{fill:#fff;stroke:#141312;stroke-width:1.1}
.tour-cur .tour-beam{left:-5px;top:-12px}
.tour-cur .tour-beam path{stroke:#141312;stroke-width:1.6;paint-order:stroke}
.tour-cur[data-look=light] .tour-arrow path{fill:#fff;stroke:#141312;stroke-width:1.1}
.tour-ring{position:absolute;left:0;top:0;z-index:7;width:46px;height:46px;margin:-23px 0 0 -23px;border-radius:50%;border:2.5px solid var(--tour-ring);background:color-mix(in srgb,var(--tour-ring) 18%,transparent);pointer-events:none;opacity:0}
/* pointer:'touch': a fingertip (44 window px, it zooms with the screen) instead of the arrow; tour.js sets its opacity and size */
.tour-touch{display:none;position:absolute;left:-22px;top:-22px;width:44px;height:44px;border-radius:50%;background:var(--tour-touch,rgba(112,112,120,.36));
  box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.62),0 0 0 1px rgba(20,19,18,.1),0 3px 12px -3px rgba(20,19,18,.32)}
.tour-cur.is-down .tour-touch{background:var(--tour-touch-down,rgba(92,92,100,.48));box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.7),0 0 0 1px rgba(20,19,18,.12),0 1px 5px -1px rgba(20,19,18,.3)}
.is-touch .tour-touch{display:block}
.is-touch .tour-cur svg{display:none!important}
.is-touch .tour-ring{width:44px;height:44px;margin:-22px 0 0 -22px;border:1.5px solid rgba(112,112,120,.55);background:none}
/* more than one pointer (steps with { by: 'agent' }): its own colour (--tour-agent) and a label tag; the person's
   cursor gets a tag too when pointers.main.label is set */
.tour-cur[data-look=agent] .tour-arrow path{fill:var(--tour-agent,#3b4bc8);stroke:#fff;stroke-width:1.4}
.tour-cur[data-look=agent] svg{filter:drop-shadow(0 1px 1.5px rgba(0,0,0,.25)) drop-shadow(0 0 7px color-mix(in srgb,var(--tour-agent,#3b4bc8) 45%,transparent))}
.tour-tag{position:absolute;left:13px;top:21px;display:flex;align-items:center;gap:6px;height:22px;padding:0 8px;border-radius:6px;background:var(--ink,#191816);color:#fff;
  font:600 11.5px/1 var(--sans,system-ui);letter-spacing:.01em;white-space:nowrap;box-shadow:0 4px 12px -4px rgba(0,0,0,.35)}
.tour-tag span{font:500 11px/1 var(--mono,ui-monospace,monospace);opacity:.82}
.tour-tag span[hidden]{display:none}
.tour-cur[data-look=agent] .tour-tag{background:var(--tour-agent,#3b4bc8)}
.tour-ring[data-who]:not([data-who=main]){--tour-ring:var(--tour-agent,#3b4bc8)}

/* chapter card: "02 / 05", a title with one italic word, one line */
.tour-card{position:absolute;z-index:6;left:var(--gutter,32px);bottom:var(--gutter,32px);width:min(calc(var(--su)*44),calc(100% - 2 * var(--gutter,32px)));
  padding:calc(var(--su)*1.8) calc(var(--su)*2.1) calc(var(--su)*2);background:var(--ph,#fff);box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 20px 44px -24px rgba(25,24,22,.45);
  opacity:0;transform:translateY(calc((1 - var(--o,0)) * 10px));pointer-events:none}
.tour-card-n{font:500 max(10.5px,calc(var(--su)*1.15))/1 var(--sans,system-ui);letter-spacing:.14em;color:var(--ink-3,#9c968c)}
.tour-card h3{margin:calc(var(--su)*1) 0 calc(var(--su)*.75);font:400 max(25px,calc(var(--su)*3.7))/1 var(--serif,Georgia,serif);letter-spacing:-.018em;color:var(--ink,#191816)}
.tour-card h3 em{font-style:italic}
.tour-card p{margin:0;font:400 max(13.5px,calc(var(--su)*1.7))/1.45 var(--sans,system-ui);color:var(--ink-2,#5f5a53)}
.tour-card,.tour-cap{transition:translate .55s cubic-bezier(.2,.7,.2,1)}
.tour-card[data-dodge=hide]{opacity:0!important}
.tour-card[data-dodge=off]{display:none}
.tour-card-x{position:absolute;top:calc(var(--su)*.9);right:calc(var(--su)*.9);width:max(26px,calc(var(--su)*2.8));height:max(26px,calc(var(--su)*2.8));display:grid;place-items:center;
  padding:0;border:0;border-radius:50%;background:transparent;color:var(--ink-3,#9c968c);font:400 max(16px,calc(var(--su)*1.9))/1 var(--sans,system-ui);cursor:pointer;pointer-events:auto;opacity:.7}
.tour-card-x:hover{opacity:1;background:var(--ph-line,#e3dfd7);color:var(--ink,#191816)}
.tour-card-x:focus-visible{outline:2px solid var(--tour-ring,#c2643f);outline-offset:2px;opacity:1}
.is-stack .tour-card{left:4%;right:4%;width:auto;bottom:auto;top:var(--card-top);padding:calc(var(--su)*2) calc(var(--su)*2.4)}
[data-tour-root].is-play:not(.is-stack) .tour-card{bottom:calc(var(--gutter,32px) + 46px)}

/* caption line: burned into recordings, because X autoplays muted */
.tour-cap{position:absolute;z-index:7;left:50%;bottom:calc(var(--su)*4);margin:0;max-width:min(calc(var(--su)*72),calc(100% - 2 * var(--gutter,32px)));width:max-content;
  padding:calc(var(--su)*1.05) calc(var(--su)*1.9);border-radius:calc(var(--su)*.6);background:var(--tour-cap-bg);color:var(--tour-cap-ink);
  font:500 max(14px,calc(var(--su)*2.35))/1.3 var(--sans,system-ui);letter-spacing:-.005em;text-align:center;opacity:0;transform:translate(-50%,calc((1 - var(--o,0)) * 8px));pointer-events:none;text-wrap:balance}
.is-stack .tour-cap{bottom:calc(var(--su)*5)}
.is-stack.is-tall .tour-cap{bottom:auto;top:var(--cap-top)}
[data-tour-root].is-play .tour-cap{bottom:calc(var(--su)*4 + 46px)}

/* key caps */
.tour-keys{position:absolute;z-index:7;display:flex;gap:calc(var(--su)*.6);transform:translate(-50%,calc((1 - var(--o,0)) * 8px));opacity:0;pointer-events:none}
.tour-keys kbd{min-width:calc(var(--su)*5.4);height:calc(var(--su)*5.4);padding:0 calc(var(--su)*1.2);display:grid;place-items:center;border-radius:calc(var(--su)*.9);
  background:var(--ph,#fff);box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 calc(var(--su)*.35) 0 var(--ph-line,#e3dfd7),0 14px 30px -16px rgba(25,24,22,.5);
  font:500 calc(var(--su)*2.4)/1 var(--sans,system-ui);color:var(--ink,#191816)}

/* play driver: one quiet bar */
.tour-ctl{position:absolute;z-index:9;left:50%;bottom:14px;transform:translateX(-50%);display:flex;align-items:center;gap:12px;width:min(620px,calc(100% - 28px));
  padding:7px 14px 7px 7px;border-radius:999px;background:color-mix(in srgb,var(--ph,#fff) 92%,transparent);box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 12px 30px -18px rgba(25,24,22,.5);
  font:500 11.5px/1 var(--mono,ui-monospace,monospace);color:var(--ink-2,#5f5a53)}
.tour-pp{flex:none;width:32px;height:32px;border:0;border-radius:50%;display:grid;place-items:center;background:var(--ink,#191816);color:var(--page,#f5f3ef);cursor:pointer}
.tour-pp svg{width:13px;height:13px;fill:currentColor}
.tour-pp:focus-visible,.tour-scrub input:focus-visible{outline:2px solid var(--note,#c2643f);outline-offset:3px}
.tour-scrub{position:relative;flex:1;height:20px;display:flex;align-items:center}
.tour-scrub::before{content:"";position:absolute;left:0;right:0;height:2px;background:var(--ph-line,#e3dfd7)}
.tour-scrub::after{content:"";position:absolute;left:0;height:2px;width:calc(var(--v,0) * 100%);background:var(--ink,#191816)}
.tour-scrub i{position:absolute;top:5px;width:1px;height:10px;background:var(--ink-3,#9c968c)}
.tour-scrub input{position:relative;z-index:1;width:100%;margin:0;background:none;-webkit-appearance:none;appearance:none;cursor:pointer;height:20px}
.tour-scrub input::-webkit-slider-thumb{-webkit-appearance:none;width:12px;height:12px;border-radius:50%;background:var(--ink,#191816)}
.tour-scrub input::-moz-range-thumb{width:12px;height:12px;border:0;border-radius:50%;background:var(--ink,#191816)}
.tour-time{flex:none;min-width:84px;text-align:right}
[data-tour-root]:not(.is-begun) .tour-ctl{opacity:0;pointer-events:none}
.tour-ctl{transition:opacity .4s ease}
.is-stack .tour-time{display:none}

/* scroll driver: the auto-play switch, the only way to take over while it plays itself */
.tour-drift{position:absolute;z-index:9;right:var(--gutter,16px);bottom:16px;display:flex;align-items:center;gap:10px;padding:7px 8px 7px 14px;border-radius:999px;
  background:color-mix(in srgb,var(--ph,#fff) 88%,transparent);box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 10px 26px -14px rgba(25,24,22,.45);
  font:500 12px/1 var(--sans,system-ui);color:var(--ink,#191816);cursor:pointer;user-select:none;transition:opacity .5s ease,transform .5s cubic-bezier(.2,.7,.2,1)}
.tour-drift input{position:absolute;opacity:0;pointer-events:none}
.tour-drift > i{position:relative;width:34px;height:20px;border-radius:999px;background:var(--ink,#191816);transition:background-color .25s}
.tour-drift > i::after{content:"";position:absolute;top:3px;left:17px;width:14px;height:14px;border-radius:50%;background:var(--page,#f5f3ef);transition:left .3s cubic-bezier(.2,.7,.2,1)}
.tour-drift:has(input:not(:checked)) > i{background:var(--rule,#d8d3c9)}
.tour-drift:has(input:not(:checked)) > i::after{left:3px}
.tour-drift:has(input:focus-visible){outline:2px solid var(--note,#c2643f);outline-offset:3px}
.tour-drift.is-gone{opacity:0;transform:translateY(8px);pointer-events:none}
.tour-say{position:absolute;right:0;bottom:calc(100% + 10px);width:max-content;max-width:min(260px,calc(100vw - 32px));padding:9px 12px;border-radius:8px;background:var(--ink,#191816);color:var(--page,#f5f3ef);
  font:500 12px/1.35 var(--sans,system-ui);opacity:0;transform:translateY(6px);pointer-events:none;transition:opacity .3s,transform .4s cubic-bezier(.2,.7,.2,1)}
.tour-drift.is-saying .tour-say{opacity:1;transform:none}
.tour-drift.is-saying{box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 0 0 4px color-mix(in srgb,var(--note,#c2643f) 35%,transparent)}

/* ?record: a clean stage of the chosen ratio, centred in the browser window, for Monet Shot to record */
html.tour-record,html.tour-record body{height:100%;overflow:hidden;background:#0e0e0d}
html.tour-record body :not([data-tour-root].is-record,[data-tour-root].is-record *,:has([data-tour-root].is-record)){display:none!important}   /* everything but the film (which may sit inside another section) */
html.tour-record .sf-note,html.tour-record .sf-spec,html.tour-record [data-tour-gate],html.tour-record [data-tour-hide-on-record]{display:none!important}
html.tour-record [data-tour-root].is-record{position:fixed;left:50%;top:50%;width:var(--rw);height:var(--rh)!important;transform:translate(-50%,-50%);z-index:2147483000;cursor:none}
html.tour-record .is-record [data-tour-stage]{position:absolute;inset:0;height:auto}

@media (prefers-reduced-motion:reduce){.tour-drift,.tour-drift *,.tour-say{transition:none}}
